/* ---------------- repair overrides: what the operator would change in the form ---------------- */
-- plain re-save, no field changes
/* ---------------- FrmAccounts validations that would refuse the save ---------------- */
IF EXISTS (SELECT 1 FROM @d WHERE LEN(GSTIN) NOT IN (0,15)) RAISERROR('GSTIN Must be Length of 15 (HQ refuses the save)',16,1);
IF EXISTS (SELECT 1 FROM @a WHERE Act_Type IN ('Customer','Supplier','Customer-Supplier')) AND EXISTS (SELECT 1 FROM @d WHERE (LEN(GSTIN)=15 AND GSTTaxType>1) OR (LEN(GSTIN)=0 AND GSTTaxType<=1))
  RAISERROR('GST type inconsistent with GSTIN (HQ refuses the save)',16,1);
IF EXISTS (SELECT 1 FROM dbo.IQAccMst m, @a a WHERE m.Act_name=REPLACE(a.Act_Name,'''','') AND m.Act_Id<>@id) RAISERROR('Account name already exists',16,1);
IF EXISTS (SELECT 1 FROM dbo.IQAccMst m, @a a WHERE m.Act_Code=REPLACE(a.Act_Code,'''','') AND m.Act_Id<>@id) RAISERROR('Account code already exists',16,1);
/* ---------------- 1. master (IQaccmst_update; regroups via IQUpdateRecOrder when Rec_higher changes) ---------------- */
DECLARE @name varchar(145), @type varchar(23), @grp int, @code varchar(60), @tt varchar(25), @bm int, @usage tinyint, @ctl int, @ct tinyint, @b2b tinyint, @sm int,
  @staff tinyint, @shift int, @att tinyint, @tcs tinyint;
