  @Act_Cat='A', @Act_TT=@tt, @Act_CA=0, @Act_OpSplit=0, @Act_St=@b2b, @Act_BillMode=@bm, @Ent_Date=@entDate, @Ent_UId=1, @Act_usage=@usage, @Act_ControlID=@ctl,
  @mCust_Type=@ct, @mBill2Bill=@b2b, @mSalesmanID=@sm, @mIsStaff=@staff, @mShift_ID=@shift, @mActTaxType=@att, @mIsTCSAPPLY=@tcs;
