  @std varchar(50),@cell varchar(50),@em varchar(100),@cst varchar(100),@sst varchar(100),@cr float,@crd int,@pan varchar(50),@tan varchar(100),@area int,@trn varchar(100),
  @mode bit,@vat varchar(100),@rate numeric(18,2),@dl20 varchar(50),@dl21 varchar(50),@sp varchar(100),@s1 varchar(200),@s2 varchar(200),@stw varchar(100),@sdi varchar(100),
  @sst2 varchar(100),@spin varchar(50),@sph1 varchar(50),@sph2 varchar(50),@sstd varchar(50),@scell varchar(50),@sem varchar(100),@aad varchar(50),@g varchar(50),
