  @di=ISNULL(NULLIF(Act_District,''),' '), @st=Act_state, @pin=ISNULL(NULLIF(Act_PinNo,''),' '), @ph1=ISNULL(NULLIF(Act_Ph1,''),' '), @ph2=ISNULL(NULLIF(Act_Ph2,''),' '),
