  @dl21=ISNULL(NULLIF(Act_DL21B,''),' '), @sp=ship_Person, @s1=ISNULL(NULLIF(ship_Add_Line1,''),' '), @s2=ISNULL(NULLIF(ship_Add_Line2,''),' '),
  @stw=ISNULL(NULLIF(ship_Act_Town,''),' '), @sdi=ISNULL(NULLIF(ship_Act_District,''),' '), @sst2=ship_Act_state, @spin=ISNULL(NULLIF(ship_Act_PinNo,''),' '),
  @sph1=ISNULL(NULLIF(ship_Act_Ph1,''),' '), @sph2=ISNULL(NULLIF(ship_Act_Ph2,''),' '), @sstd=ISNULL(NULLIF(ship_Act_STD,''),' '),
